import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是仓库级的低库存阈值配置，相对仓库根。
const thresholdsFile = "config/thresholds.json"

// thresholdsPathEnv 可把配置文件指到别处（部署时工作目录未必在仓库根）。
const thresholdsPathEnv = "INVENTORY_THRESHOLDS_FILE"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 config/thresholds.json：配了这个仓库就用配置值，没配就回退到
// DefaultLowStockThreshold。每次调用都重新读文件，所以改配置不需要重新构建。
func LowStockThreshold(warehouse string) int {
	return thresholdFor(loadThresholds(), warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	thresholds := loadThresholds()
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if quantity < thresholdFor(thresholds, warehouse) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// thresholdFor 返回仓库的阈值：配了就用配置值（包括配成 0），没配才用默认值。
func thresholdFor(thresholds map[string]int, warehouse string) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析配置文件。文件不存在或解析失败都当作"没配置"，
// 让调用方回退到默认值。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsPath())
	if err != nil {
		return nil
	}
	thresholds := map[string]int{}
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// thresholdsPath 定位配置文件：优先用 INVENTORY_THRESHOLDS_FILE，否则从当前
// 工作目录逐级向上找，兼容从仓库根跑二进制和从 inventory/ 里跑测试两种情况。
func thresholdsPath() string {
	if path := os.Getenv(thresholdsPathEnv); path != "" {
		return path
	}
	dir, err := os.Getwd()
	if err != nil {
		return thresholdsFile
	}
	for {
		candidate := filepath.Join(dir, thresholdsFile)
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return thresholdsFile
		}
		dir = parent
	}
}

