package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

func TestManualVerify(t *testing.T) {
	// 1) 仓库里自带的 config/thresholds.json（测试从 inventory/ 运行，需向上找到）
	if got := LowStockThreshold("beijing"); got != 10 {
		t.Fatalf("beijing = %d, 期望配置值 10", got)
	}
	if got := LowStockThreshold("shanghai"); got != 3 {
		t.Fatalf("shanghai = %d, 期望配置值 3", got)
	}

	// 2) 未配置仓库回退默认
	for _, wh := range []string{"chengdu", "wuhan", "xian", "nonexistent"} {
		if got := LowStockThreshold(wh); got != DefaultLowStockThreshold {
			t.Fatalf("%s = %d, 期望默认值 %d", wh, got, DefaultLowStockThreshold)
		}
	}

	// 3) 运行时改文件立即生效（无需重建/重启）
	dir := t.TempDir()
	path := filepath.Join(dir, "thresholds.json")
	t.Setenv(thresholdsPathEnv, path)

	if err := os.WriteFile(path, []byte(`{"beijing": 2}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("beijing"); got != 2 {
		t.Fatalf("改文件后 beijing = %d, 期望 2", got)
	}
	if err := os.WriteFile(path, []byte(`{"beijing": 7}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("beijing"); got != 7 {
		t.Fatalf("再次改文件后 beijing = %d, 期望 7", got)
	}

	// 4) 配成 0 覆盖默认值（0 是有效配置，不是"未配置"）
	if err := os.WriteFile(path, []byte(`{"beijing": 0}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("beijing"); got != 0 {
		t.Fatalf("beijing = %d, 期望配置的 0", got)
	}
	if IsLowStock("beijing", 0) {
		t.Fatal("阈值 0 时库存 0 不应算低库存")
	}

	// 5) 文件缺失 / JSON 损坏都回退默认
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("缺文件时 beijing = %d, 期望默认值", got)
	}
	if err := os.WriteFile(path, []byte(`{not json`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("坏 JSON 时 beijing = %d, 期望默认值", got)
	}

	// 6) 批量判定按各自阈值
	if err := os.WriteFile(path, []byte(`{"beijing": 10, "shanghai": 1}`), 0o644); err != nil {
		t.Fatal(err)
	}
	got := LowStockWarehouses(map[string]int{"beijing": 9, "shanghai": 1, "chengdu": 4})
	want := map[string]bool{"beijing": true, "chengdu": true}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
	for _, wh := range got {
		if !want[wh] {
			t.Fatalf("LowStockWarehouses 多出 %q", wh)
		}
	}
}
